ference"},{"url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000537491_Tussen_de_regels_0_0.jpg","checkedAt":"2026-10-31T23:12:22.694Z","sha256":"c7a86627c92b5dd4042964f9dc474aeefa15f12aa26ab9c8ef285b9c74255dae","bytes":600946,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789021475202","work_id":1429,"bound_author_id":753,"bound_title":"Tussen de regels","bound_language":"nld","bound_isbn13":"9789021475202","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000537491_Tussen_de_regels_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html"}},{"relation":"catalog_work_descriptions","ref":"description:1429:nl","key":{"work_id":1429,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000537491_Tussen_de_regels_0_0.jpg","checkedAt":"2026-10-31T23:12:22.694Z","sha256":"c7a86627c92b5dd4042964f9dc474aeefa15f12aa26ab9c8ef285b9c74255dae","bytes":600946,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":1429,"language":"nl","bound_author_id":753,"text":"Rowan moet een opdracht binnen het pretpark Dreamland uitvoeren om een erfenis veilig te stellen. Zahra kent het park vanuit haar werk en neemt geen genoegen met de manier waarop sommige zaken zijn geregeld. Hun zakelijke contact krijgt daardoor al snel een persoonlijk karakter. De roman volgt hoe verschillende belangen en ervaringen hun omgang beïnvloeden, terwijl aantrekkingskracht de afstand tussen werkgever en werknemer ingewikkelder maakt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1618138/tussen-de-regels.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022566923","key":{"isbn_13":"9789022566923"},"before":null,"after":{"work_id":1466,"title":"Terugkeer naar Inverness","isbn_13":"9789022566923","isbn_10":"9022566927","language":"nld","publisher":"Meulenhoff Boekerij B.V."}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022566923","key":{"edition_id":"@edition:9789022566923"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/297413/terugkeer-naar-inverness.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.bibliotheek.nl/catalogus/titel.362787344.html/terugkeer-naar-inverness/","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000521324_Terugkeer_naar_Inverness_0_0.jpg","checkedAt":"2026-10-31T23:12:24.526Z","sha256":"fa64b5d551fd2dc8c32782ddb8de691c6ac71ee8f9ca40ab63e432bb5b17ed45","bytes":478389,"fact":"Manual title/author/exact edition cover binding, readable published front"},{"reviewNote":"Bureau blurb describes20year reunion/Voyager rather than book2; new summary based on exact library Dragonfly/1745 evidence instead"}],"edition_id":"@edition:9789022566923","work_id":1466,"bound_author_id":55,"bound_title":"Terugkeer naar Inverness","bound_language":"nld","bound_isbn13":"9789022566923","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000521324_Terugkeer_naar_Inverness_0_0.jpg","card_cover_url":null,"ev