atalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1810349/huis-van-vuur-schaduw.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789463107952","key":{"isbn_13":"9789463107952"},"before":null,"after":{"work_id":1914,"title":"Reckless","isbn_13":"9789463107952","isbn_10":"9463107959","language":"nld","publisher":"Pelckmans uitgevers"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789463107952","key":{"edition_id":"@edition:9789463107952"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1941074/reckless.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1941074/reckless.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000646651_Reckless_0_0.jpg","checkedAt":"2026-10-31T23:12:30.006Z","sha256":"39895088d433f73997068418f3407ab811e2ddff3f3e2676a9dcf4821269f13b","bytes":466110,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789463107952","work_id":1914,"bound_author_id":737,"bound_title":"Reckless","bound_language":"nld","bound_isbn13":"9789463107952","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000646651_Reckless_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1941074/reckless.html"}},{"relation":"catalog_work_descriptions","ref":"description:1914:nl","key":{"work_id":1914,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1941074/reckless.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1941074/reckless.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000646651_Reckless_0_0.jpg","checkedAt":"2026-10-31T23:12:30.006Z","sha256":"39895088d433f73997068418f3407ab811e2ddff3f3e2676a9dcf4821269f13b","bytes":466110,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":1914,"language":"nl","bound_author_id":737,"text":"Na de gebeurtenissen in Ilya moet Paedyn vluchten. Kai krijgt als nieuwe Handhaver opdracht haar op te sporen, hoewel zijn gevoelens die taak bemoeilijken. De achtervolging brengt hen in een vijandige omgeving waar geen van beiden zich op vertrouwde zekerheden kan verlaten. Het tweede Powerless-boek zet hun persoonlijke band onder druk door bevelen van het hof, gevaar en de gevolgen van eerdere keuzes.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1941074/reckless.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789463839907","key":{"isbn_13":"9789463839907"},"before":null,"after":{"work_id":1915,"title":"Fearless","isbn_13":"9789463839907","isbn_10":"9463839909","language":"nld","publisher":"Pelckmans uitgevers"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789463839907","key":{"edition_id":"@edition:9789463839907"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1970514/fearless.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1970514/fearless.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000709403_Fearless_0_0.jpg","checkedAt":"2026-10-31T23:12:31.855Z