e_reviewed_summary"}},{"relation":"editions","ref":"edition:9789062226856","key":{"isbn_13":"9789062226856"},"before":null,"after":{"work_id":1916,"title":"King of envy","isbn_13":"9789062226856","isbn_10":"906222685X","language":"nld","publisher":"Singel Uitgeverijen"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789062226856","key":{"edition_id":"@edition:9789062226856"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/2048707/king-of-envy.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/2048707/king-of-envy.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000743517_King_of_envy_0_0.jpg","checkedAt":"2026-10-31T23:12:33.677Z","sha256":"560900ccbf7def396f8df791ceef624322f39d0befd9a1a0ed04fc53e05247ff","bytes":480669,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789062226856","work_id":1916,"bound_author_id":405,"bound_title":"King of envy","bound_language":"nld","bound_isbn13":"9789062226856","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000743517_King_of_envy_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/2048707/king-of-envy.html"}},{"relation":"catalog_work_descriptions","ref":"description:1916:nl","key":{"work_id":1916,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/2048707/king-of-envy.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/2048707/king-of-envy.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000743517_King_of_envy_0_0.jpg","checkedAt":"2026-10-31T23:12:33.677Z","sha256":"560900ccbf7def396f8df791ceef624322f39d0befd9a1a0ed04fc53e05247ff","bytes":480669,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":1916,"language":"nl","bound_author_id":405,"text":"Voor de buitenwereld heeft model Ayana Kidane haar leven goed op orde. Haar verloving is echter onderdeel van een zakelijke afspraak die haar onafhankelijkheid moet brengen. Vuk Markovic, een vriend van haar verloofde, maakt dat plan ingewikkelder. Tussen aantrekkingskracht, loyaliteit en verborgen belangen ontstaat een verhouding die niet binnen de afgesproken grenzen blijft. Dit vijfde Kings of Sin-boek draait om de prijs van zekerheid en verlangen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2048707/king-of-envy.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789403142333","key":{"isbn_13":"9789403142333"},"before":null,"after":{"work_id":1919,"title":"Het onmogelijke fortuin","isbn_13":"9789403142333","isbn_10":"9403142332","language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403142333","key":{"edition_id":"@edition:9789403142333"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/2144139/het-onmogelijke-fortuin.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.standaardboekhandel.be/p/het-onmogelijke-fortuin-9789403142333","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000799717_Het_onmogelijke_fortuin_0_0.jpg