ource_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2144139/het-onmogelijke-fortuin.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464822076","key":{"isbn_13":"9789464822076"},"before":null,"after":{"work_id":1917,"title":"Hopeloos","isbn_13":"9789464822076","isbn_10":"9464822074","language":"nld","publisher":"April Books"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464822076","key":{"edition_id":"@edition:9789464822076"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000644321_Hopeloos_0_0.jpg","checkedAt":"2026-10-31T23:12:37.32Z","sha256":"3780bf8c488c04ba0f362c7c970c286af56790d64b2471bf195d4e013ff3a26a","bytes":834864,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789464822076","work_id":1917,"bound_author_id":971,"bound_title":"Hopeloos","bound_language":"nld","bound_isbn13":"9789464822076","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000644321_Hopeloos_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1829947/hopeloos.html"}},{"relation":"catalog_work_descriptions","ref":"description:1917:nl","key":{"work_id":1917,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1829947/hopeloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000644321_Hopeloos_0_0.jpg","checkedAt":"2026-10-31T23:12:37.32Z","sha256":"3780bf8c488c04ba0f362c7c970c286af56790d64b2471bf195d4e013ff3a26a","bytes":834864,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":1917,"language":"nl","bound_author_id":971,"text":"Beau en Bailey kennen hetzelfde stadje, maar hun levens verschillen sterk. Hij staat bekend als een militaire held; zij werkt in de plaatselijke bar en voelt zich vaak buitengesloten. Een afspraak om een verloving te veinzen brengt hen dichter bij elkaar. Het laatste Chestnut Springs-boek volgt hoe hun praktische regeling verandert wanneer de nabijheid niet meer zo eenvoudig van echte gevoelens te scheiden is.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1829947/hopeloos.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464821321","key":{"isbn_13":"9789464821321"},"before":null,"after":{"work_id":2003,"title":"Machteloos","isbn_13":"9789464821321","isbn_10":"9464821329","language":"nld","publisher":"April Books"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464821321","key":{"edition_id":"@edition:9789464821321"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1801097/machteloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1801097/machteloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000628427_Machteloos_0_0.jpg","checkedAt":"2