"provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022570937","key":{"isbn_13":"9789022570937"},"before":null,"after":{"work_id":2199,"title":"Het vlammende kruis","isbn_13":"9789022570937","isbn_10":"9022570932","language":"nld","publisher":"Meulenhoff Boekerij B.V."}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022570937","key":{"edition_id":"@edition:9789022570937"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/97185/het-vlammende-kruis.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.lannoo.com/nl-be/literatuur-romans/het-vlammende-kruis-9789022570937","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000520843_Het_vlammende_kruis_0_0.jpg","checkedAt":"2026-10-31T23:12:41.329Z","sha256":"fd86bb456fc630928bd2dd895a0f22ddf5c929e092e548a2a16852d238589243","bytes":581775,"fact":"Manual title/author/exact edition cover binding, readable published front"},{"reviewNote":"Publisher/Bureau CivilWar wording rejected; independent historical period not inferred from bad blurb"}],"edition_id":"@edition:9789022570937","work_id":2199,"bound_author_id":55,"bound_title":"Het vlammende kruis","bound_language":"nld","bound_isbn13":"9789022570937","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000520843_Het_vlammende_kruis_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/97185/het-vlammende-kruis.html"}},{"relation":"catalog_work_descriptions","ref":"description:2199:nl","key":{"work_id":2199,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/97185/he