igieuze organisatie in Norfolk. Achter het vreedzame publieke beeld vermoedt de detective ernstige misstanden. Robin Ellacott gaat undercover om van binnenuit bewijs te verzamelen. Hun zevende zaak draait om de afstand tussen een zorgvuldig opgebouwde reputatie en de ervaringen van mensen die steeds moeilijker aan de gemeenschap kunnen ontsnappen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1724145/tijdelijke-titel-deel-7-comoran-strike.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464821307","key":{"isbn_13":"9789464821307"},"before":null,"after":{"work_id":2518,"title":"Harteloos","isbn_13":"9789464821307","isbn_10":"9464821302","language":"nld","publisher":"April Books"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464821307","key":{"edition_id":"@edition:9789464821307"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000628186_Harteloos_0_0.jpg","checkedAt":"2026-10-31T23:12:45.045Z","sha256":"1d68c741523467b61e4b5b742e4594e0b44a15284064e41971a7dabbc893edff","bytes":702410,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789464821307","work_id":2518,"bound_author_id":971,"bound_title":"Harteloos","bound_language":"nld","bound_isbn13":"9789464821307","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000628186_Harteloos_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1799797/harteloos.html"}},{"relation":"catalog_work_descriptions","ref":"description:2518:nl","key":{"work_id":2518,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1799797/harteloos.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000628186_Harteloos_0_0.jpg","checkedAt":"2026-10-31T23:12:45.045Z","sha256":"1d68c741523467b61e4b5b742e4594e0b44a15284064e41971a7dabbc893edff","bytes":702410,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2518,"language":"nl","bound_author_id":971,"text":"Cade heeft hulp nodig om zijn werk op de ranch te combineren met de zorg voor zijn zoon Luke. Willa komt voor de zomer als oppas werken. Hij wil de verhouding zakelijk houden, maar haar aanwezigheid verandert gaandeweg het dagelijks leven van het gezin. Het tweede Chestnut Springs-boek volgt hoe hun verschillende verwachtingen botsen met een aantrekkingskracht waarvoor de tijdelijke arbeidsovereenkomst geen duidelijke regels biedt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1799797/harteloos.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789464822052","key":{"isbn_13":"9789464822052"},"before":null,"after":{"work_id":1910,"title":"Roekeloos","isbn_13":"9789464822052","isbn_10":"9464822058","language":"nld","publisher":"April Books"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789464822052","key":{"edition_id":"@edition:9789464822052"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evi