26-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000059588_Kou_uit_het_oosten_0_0.jpg","checkedAt":"2026-10-31T23:12:50.557Z","sha256":"7579dbdcdd53f31d782779fccba5d6f40160cad9000090a0dd010c4237156719","bytes":79512,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2206,"language":"nl","bound_author_id":358,"text":"Jonge mensen uit verschillende families zoeken hun weg in een wereld die door de Koude Oorlog wordt verdeeld. Rebecca krijgt in Oost-Duitsland met de Stasi te maken, George raakt betrokken bij de Amerikaanse burgerrechtenstrijd en anderen werken dicht bij politieke machthebbers. Het slot van de Century-trilogie verbindt hun persoonlijke keuzes met internationale spanningen en maatschappelijke veranderingen die de tweede helft van de twintigste eeuw tekenen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/263870/kou-uit-het-oosten.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022599280","key":{"isbn_13":"9789022599280"},"before":null,"after":{"work_id":2251,"title":"De schemering en de dageraad","isbn_13":"9789022599280","isbn_10":"9022599280","language":"nld","publisher":"Meulenhoff Boekerij B.V."}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022599280","key":{"edition_id":"@edition:9789022599280"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1294704/de-schemering-en-de-dageraad.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1294704/de-schemering-en-de-dageraad.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/1993334/","checkedAt":"20