n botenbouwer verliest zijn vertrouwde omgeving, een Normandische vrouw ontdekt de harde kanten van haar nieuwe land en een monnik wil zijn abdij ontwikkelen. Hun levens raken verbonden rond de plaats die later Kingsbridge wordt, waar een invloedrijke bisschop zijn eigen belangen verdedigt.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1294704/de-schemering-en-de-dageraad.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789041715951","key":{"isbn_13":"9789041715951"},"before":null,"after":{"work_id":2216,"title":"Meester Legende","isbn_13":"9789041715951","isbn_10":"9041715959","language":"nld","publisher":"Uitgeverij Rainbow bv"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041715951","key":{"edition_id":"@edition:9789041715951"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://cdn.boekhub.overamstel.com/omnifiles/Rainbow_brochure_V24_LR_2.pdf","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","checkedAt":"2026-10-31T23:12:54.204Z","sha256":"a098838652f1b7ff7857c5cee988daff3c2fb39f1650153de3a8a154e0d180dd","bytes":454712,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789041715951","work_id":2216,"bound_author_id":735,"bound_title":"Meester Legende","bound_language":"nld","bound_isbn13":"9789041715951","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html"}},{"relation":"catalog_work_descriptions","ref":"description:2216:nl","key":{"work_id":2216,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://cdn.boekhub.overamstel.com/omnifiles/Rainbow_brochure_V24_LR_2.pdf","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000621239_Caraval_2_-_Meester_Legende_0_0.jpg","checkedAt":"2026-10-31T23:12:54.204Z","sha256":"a098838652f1b7ff7857c5cee988daff3c2fb39f1650153de3a8a154e0d180dd","bytes":454712,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2216,"language":"nl","bound_author_id":735,"text":"Donatella doet opnieuw mee aan een voorstelling van Caraval, ditmaal tijdens een bijzonder feest voor de keizerin. Naast het zichtbare spel heeft ze een eigen opdracht: informatie over haar verdwenen moeder verkrijgen. Daarvoor moet ze de ware identiteit van meester Legende achterhalen. Het vervolg op Caraval maakt haar zoektocht steeds ingewikkelder wanneer nieuwsgierigheid, gevaar en gevoelens voor de raadselachtige spelmeester door elkaar gaan lopen.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1778231/caraval-2-meester-legende.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789041716316","key":{"isbn_13":"9789041716316"},"before":null,"after":{"work_id":2219,"title":"Finale","isbn_13":"9789041716316","isbn_10":"9041716319","language":"nld","publisher":"Uitgeverij Rainbow bv"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041716316","key":{"edition_id":"@edition:9789041716316"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/2295073/","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","checkedAt":"2026-10-31T23:14:50.205Z","sha256":"63a1e14bb13fbc877a304fe42af8e468ed7fe26d92ee8180ab4d8d55587e615e","bytes":415919,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789041716316","work_id":2219,"bound_author_id":735,"bound_title":"Finale","bound_language":"nld","bound_isbn13":"9789041716316","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1934957/finale.html"}},{"relation":"catalog_work_descriptions","ref":"description:2219:nl","key":{"work_id":2219,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1934957/finale.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://rozet.nl/catalogus/2295073/","checkedAt":"2026-11-01","fact":"Independent identity/content corroboration"},{"url":"https://metadata.isbn.nl/ie_fcache/0000694689_Finale_0_0.jpg","checkedAt":"2026-10-31T23:14:50.205Z","sha256":"63a1e14bb13fbc877a304fe42af8e468ed7fe26d92ee8180ab4d8d55587e615e","bytes":415919,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2219,"language":"nl","bound_author_id":735,"text":"Voor Scarlett en Donatella houdt de onzekerheid niet op wanneer Caraval voorbij is. Hun wereld wordt bedreigd door vrijgekomen machten en de gevolgen van eerdere keuzes. Tella moet bepalen wie zij kan vertrouwen, terwijl ook haar zus een moeilijke opdracht krijgt. Het laatste boek van de trilogie verplaatst de inzet van een georganiseerde voorstelling naar een werkelijkheid waarin liefde, familie en de identiteit van Legende steeds belangrijker worden.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1934957/finale.html","provenance":"original_source_reviewed_summary"}}],"bindings":[{"work":{"id":1412,"title":"The Ballad of Never After","cover_id":null,"subjects":null,"subtitle":null,"author_id":735,"work_type":null,"created_at":"2026-09-16T15:07:31.588548+00:00","source_type":"open_library","open_library_id":"OL27090610W","first_publish_year":2022,"native_identity_key":null},"author":{"id":735,"name":"Stephanie Garber","created_at":"2026-09-16T15:06:17.891634+00:00","open_library_id":"OL7387659A"}},{"work":{"id":1429,"title":"The Fine Print","cover_id":null,"subjects":null,"subtitle":null,"author_id":753,"work_type":null,"created_at":"2026-09-16T15:08:18.268551+00:00","source_type":"open_library","open_library_id":"OL26201864W","first_publish_year":2021,"native_identity_key":null},"author":{"id":753,"name":"Lauren Asher","created_at":"2026-09-16T15:08:18.028811+00:00","open_library_id":"OL9236836A"}